if (!root) {
    root = new TreeNode(item);
    return;
}
if (item < root->data) {
    avlInsert(root->left, item);
} else if (item > root->data) {
    avlInsert(root->right, item);
} else {
    return; // duplicate keys not allowed
}
int lh = root->left ? root->left->height : 0;
int rh = root->right ? root->right->height : 0;
root->height = std::max(lh, rh) + 1;
int balance = lh - rh;
if (balance > 1 && item < root->left->data) {
    avlRotateRight(root);
} else if (balance < -1 && item > root->right->data) {
    avlRotateLeft(root);
} else if (balance > 1 && item > root->left->data) {
    avlRotateLeft(root->left);
    avlRotateRight(root);
} else if (balance < -1 && item < root->right->data) {
    avlRotateRight(root->right);
    avlRotateLeft(root);
}

